import {elevatorEase,sampleElevatorTravel} from './elevator-motion.js';
import {SCHOOL_FLOORS,floorForWorld,SCHOOL_ELEVATOR} from '../world/school-floor-layout.js';
const clampDt=dt=>Number.isFinite(dt)?Math.max(0,Math.min(.05,dt)):0;
export function createElevatorController({ui,getView,getPlayer,transition,cancelTransition=()=>{},clearInput=()=>{},onChange=()=>{},isAllowed=()=>true,ride=null,reduced=false,document:doc=globalThis.document,window:win=globalThis.window}){
 let flight=null,selection=null,generation=0,paused=false,disposed=false;const listeners=[];
 const status=()=>doc?.querySelector?.('#elevator-status');
 const report=text=>{const node=status();if(node){node.hidden=!text;node.textContent=text;}};
 function listen(node,type,fn){node?.addEventListener?.(type,fn);listeners.push([node,type,fn]);}
 function finish(f){if(flight!==f)return;f.view?.elevator?.setOpen(1);f.view?.elevator?.setTravel();ride?.finish();flight=null;report('');clearInput();onChange();}
 function waitFor(f,phase){return new Promise((resolve,reject)=>{if(flight!==f||f.cancelled){reject(Error('ElevatorCancelled'));return;}f.waiters.push({phase,resolve,reject});});}
 function signal(f,phase){for(const w of f.waiters.filter(w=>w.phase===phase))w.resolve();f.waiters=f.waiters.filter(w=>w.phase!==phase);}
 function cancel(){generation++;selection=null;if(!flight)return;const f=flight;clearInput();if(f.committed){f.phase='open';f.view.elevator.setOpen(1);signal(f,'open');finish(f);return;}f.cancelled=true;cancelTransition();for(const w of f.waiters)w.reject(Error('ElevatorCancelled'));f.waiters=[];finish(f);}
 async function choose(number,token){const from=floorForWorld(getView()?.worldId),destination=SCHOOL_FLOORS.find(f=>f.number===number);if(disposed||flight||!selection||selection.token!==token||!from||!destination)return false;
  if(!getView().elevator.inside(getPlayer(),SCHOOL_ELEVATOR.radius)){ui.toast('문 안쪽으로 조금 더 들어와 주세요');return false;}
  selection=null;ui.close();if(from===destination)return true;const view=getView(),f={token:++generation,view,from:from.number,to:number,phase:'closing',time:0,waiters:[],cancelled:false,committed:false};flight=f;clearInput();ride?.start(view);view.elevator.setTravel?.({...sampleElevatorTravel(f.from,f.to,0,reduced),from:f.from,destination:f.to});onChange();report(number+'층으로 이동할 준비를 해요');
  const presentation={...(ride?{fade:async()=>{}}:{}),async beforeCommit(next){if(flight!==f||f.cancelled)throw Error('ElevatorCancelled');if(f.phase==='closing')await waitFor(f,'closed');if(flight!==f||f.cancelled)throw Error('ElevatorCancelled');f.phase='travelling';f.time=0;report(number+'층으로 이동 중');await waitFor(f,'travelled');if(flight!==f||f.cancelled)throw Error('ElevatorCancelled');next.elevator?.setOpen(0);next.elevator?.setTravel?.({...sampleElevatorTravel(f.from,f.to,100,reduced),from:f.from,destination:f.to});},didCommit(next){f.view=next;ride?.setView(next);f.committed=true;f.phase='arriving';f.time=0;},async afterEnter(){if(flight!==f)return;f.phase='opening';f.time=0;report(number+'층에 도착했어요');await waitFor(f,'open');}};
  let outcome;try{outcome=await transition({roomId:destination.hallId,spawnId:'from-elevator'},{presentation});}catch{outcome='failed';}if(flight===f){if(outcome==='failed')ui.toast('층을 열지 못했어요. 지금 층에서 다시 골라 주세요');finish(f);}return outcome==='entered';
 }
 function open(){if(disposed||flight||selection||!isAllowed())return false;const view=getView(),from=floorForWorld(view?.worldId);if(!from)return false;if(!view.elevator?.inside(getPlayer(),SCHOOL_ELEVATOR.radius)){ui.toast('엘리베이터 문 안쪽으로 들어와 주세요');return false;}const token=++generation;selection={token};const ok=ui.workshop('엘리베이터 · '+from.number+'층',`<div class="elevator-choices">${SCHOOL_FLOORS.map(f=>`<button data-elevator-floor="${f.number}"${f.number===from.number?' aria-current="true"':''}><strong>${f.number}층${f.number===from.number?' · 지금 여기':''}</strong><span>${f.short}</span></button>`).join('')}</div>`,()=>{const bound=[];for(const button of doc.querySelectorAll('[data-elevator-floor]')){const fn=()=>choose(Number(button.dataset.elevatorFloor),token);button.addEventListener('click',fn);bound.push([button,fn]);}return()=>{for(const[b,fn]of bound)b.removeEventListener('click',fn);if(selection?.token===token)selection=null;};},{kind:'elevator-selector',closeLabel:'그대로 있기'});if(!ok&&selection?.token===token)selection=null;return ok;}
 function tick(dt){const f=flight;if(!f||paused||doc?.hidden)return;const d=clampDt(dt),doorTime=reduced?.12:.55,openTime=reduced?.12:.60;f.time+=d;
  if(f.phase==='closing'){f.view.elevator.setOpen(1-elevatorEase(f.time/doorTime));if(f.time>=doorTime){f.phase='waiting';f.time=0;report(f.to+'층을 준비하고 있어요');signal(f,'closed');}}
  else if(f.phase==='travelling'){const motion=sampleElevatorTravel(f.from,f.to,f.time,reduced);f.view.elevator.setTravel?.({...motion,from:f.from,destination:f.to});if(motion.floor!==f.lastFloor){f.lastFloor=motion.floor;report(motion.floor+'층 · '+(f.to>f.from?'올라가는 중':'내려가는 중'));}if(motion.arrived){f.phase='waiting-arrival';signal(f,'travelled');}}
  else if(f.phase==='opening'){f.view.elevator.setOpen(elevatorEase(f.time/openTime));if(f.time>=openTime){f.phase='open';signal(f,'open');}}
 }
 listen(win,'blur',()=>{paused=true;clearInput();});listen(win,'focus',()=>{paused=false;});listen(doc,'visibilitychange',()=>{if(doc.hidden)clearInput();});listen(win,'keydown',event=>{if(event.code==='Escape'&&flight){event.preventDefault();cancel();}});
 return{open,tick,cancel,get active(){return !!flight;},get camera(){return ride?.camera??null;},fitCamera(width,height){return ride?.fit(width,height);},snapshot:()=>flight?{from:flight.from,to:flight.to,phase:flight.phase,paused,committed:flight.committed,open:flight.view.elevator.open,travel:flight.view.elevator.snapshot?.().travel??null}:null,dispose(){if(disposed)return;cancel();disposed=true;for(const[n,t,f]of listeners)n?.removeEventListener?.(t,f);listeners.length=0;}};
}
